  COMPREPLY=( $(compgen -W "$(for d in "${_shai_dir}/workflows/"*/run.sh; do [ -f "$d" ] || continue; d="${d%/run.sh}"; n="${d##*/}"; p="$(sed -n '2s/^# //p' "$d/run.sh" 2>/dev/null)"; p="${p##*— }"; printf '%s\t%s\n' "$n" "$p"; done 2>/dev/null | cut -f1)" -- "$cur") )
}
